import math
def donut(parts, size=150, stroke=20):
    r = (size - stroke) / 2.0; c = 2 * math.pi * r; tot = float(sum(v for _, v, _ in parts)); off = 0; segs_ = ''
    for _, v, col in parts:
        L = c * v / tot
        segs_ += '<circle cx="%s" cy="%s" r="%s" fill="none" stroke="%s" stroke-width="%d" stroke-dasharray="%.2f %.2f" stroke-dashoffset="%.2f"></circle>' % (size/2, size/2, r, col, stroke, max(L - 2, 0.5), c, -off)
        off += L
    return '<svg width="%d" height="%d" viewBox="0 0 %d %d" aria-hidden="true" style="transform: rotate(-90deg); flex-shrink: 0">%s</svg>' % (size, size, size, size, segs_)
